 "content": "def transform(grid):
    """Decode each 3x3 cell, keeping its non-background marker color."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("grid dimensions must be divisible by 3")
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            colors = {grid[y][x] for y in range(r, r + 3) for x in range(c, c + 3)} - {0, 5}
            if len(colors) > 1:
                raise ValueError(f"ambiguous tile at {(r // 3, c // 3)}: {colors}")
            row.append(next(iter(colors), 0))
        out.append(row)
    return out
